server.registerTool(
  "wwkj_conn_status",
  {
    title: "连接器状态",
    description: "查看连接器当前状态：网关地址、服务域（global/patrol/train 的壳前缀）、登录身份、壳令牌有效期、登录凭据类型（密码可静默重登 / 验证码到期需重新发码）、只读开关与写操作白名单、审计留痕文件。排查问题第一步。",
    inputSchema: {}
  },
  async () => {
    try {
      const now = Date.now();
      const fmtToken = () => {
        if (!state.login) return "未登录";
        const left = Math.round((state.login.expireAt - now) / 1e3);
        return left > 0 ? `有效，剩余约 ${left}s（到期后自动按登录方式处理）` : "已过期（下次调用会触发重登）";
      };
      const credType = state.cred ? state.cred.type === "password" ? "账号密码（会话内已保存凭据；令牌到期可静默重登）" : "短信验证码（验证码不可重放；令牌到期需重新发码登录）" : "无（尚未登录；或使用配置式凭据自动登录）";
      const idView = IDENTITY.describe();
      const info = {
        概览: {
          连接状态: state.login ? "已登录" : "未登录",
          当前身份: state.login ? `${idView.用户姓名uname}（企业 ${idView.企业编码ent}，账号 ${idView.登录账号uid}）` : "尚未登录；需要先在对话里完成登录认证",
          使用限制: CFG.readOnly ? "只读 —— 只支持查询，不会改动任何数据" : "可读写 —— 每次写操作都会先向你确认一次"
        },
        诊断详情: {
          版本: VERSION,
          网关地址: CFG.gatewayUrl || "（未配置 —— 需设置 WWKJ_GATEWAY_URL）",
          通道: "壳通道（唯一通道）：/shellauth/** 认证 + /shell/{服务前缀}/** 代理",
          服务域: describeDomains(),
          身份策略: idView.身份拒绝开关,
          单身份约束: idView.单身份约束,
          登录凭据: credType,
          壳令牌: fmtToken(),
          配置登录密码: CFG.password ? "已配置（不显示）" : "（未配置，走对话式登录）",
          写操作管控: WRITES.describe(),
          审计留痕: AUDIT.describe(),
          超时毫秒: CFG.timeoutMs,
          会话Cookie: [...cookieJar.keys()].length ? [...cookieJar.keys()].join(", ") : "无"
        }
      };
      return ok(info);
    } catch (e) {
      return fail(e);
    }
  }
);
