async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  log(
    `已启动 v${VERSION}；通道=shell（唯一）；网关=${CFG.gatewayUrl || "未配置"}；身份冻结=${CFG.identityLock ? "开" : "关"}；只读=${CFG.readOnly ? "开" : "关"}`
  );
}
main().catch((e) => {
  log(`启动失败：${e && e.stack ? e.stack : e}`);
  process.exit(1);
});
